class Solution {
  private static final int[] DIGITS = {0, 1, 6, 8, 9}, ROT = {0, 1, 9, 8, 6};
  private int n, count;

  public int confusingNumberII(int n) {
    this.n = n;
    // build every number of rotatable digits, tracking its rotation as we go
    for (int i = 1; i < 5; i++) build(DIGITS[i], ROT[i], 10);
    return count;
  }

  // rotated = rotation of num; mult = 10^(digit count of num)
  private void build(long num, long rotated, long mult) {
    if (num > n) return;
    if (num != rotated) count++;
    for (int i = 0; i < 5; i++) build(num * 10 + DIGITS[i], ROT[i] * mult + rotated, mult * 10);
  }
}
